import React, { useEffect, useRef, useState } from "react";
import {
  Bell,
  Search,
  User,
  X,
  LogOut,
  Package,
  Users,
  LayoutDashboard,
  ClipboardList
} from "lucide-react";

import { Link, useLocation, useNavigate } from "react-router-dom";

export default function StaffNavbar() {

  const location = useLocation();
  const navigate = useNavigate();

  const [openSearch, setOpenSearch] = useState(false);
  const [openNotif, setOpenNotif] = useState(false);
  const [openAccount, setOpenAccount] = useState(false);

  const [search, setSearch] = useState("");
  const [products, setProducts] = useState([]);

  const searchRef = useRef(null);
  const notifRef = useRef(null);
  const accountRef = useRef(null);

  /* =========================
     FETCH PRODUCTS
  ========================= */

  useEffect(() => {

    fetch(
      "http://localhost/pastry_system/customer/api_products.php?action=list"
    )
      .then(res => res.json())
      .then(data => {

        if (Array.isArray(data)) {
          setProducts(data);
        }

      })
      .catch(() => setProducts([]));

  }, []);

  /* =========================
     CLOSE DROPDOWNS
  ========================= */

  useEffect(() => {

    const handleOutside = (e) => {

      if (
        searchRef.current &&
        !searchRef.current.contains(e.target)
      ) {
        setOpenSearch(false);
      }

      if (
        notifRef.current &&
        !notifRef.current.contains(e.target)
      ) {
        setOpenNotif(false);
      }

      if (
        accountRef.current &&
        !accountRef.current.contains(e.target)
      ) {
        setOpenAccount(false);
      }

    };

    document.addEventListener(
      "mousedown",
      handleOutside
    );

    return () =>
      document.removeEventListener(
        "mousedown",
        handleOutside
      );

  }, []);

  /* =========================
     SEARCH FILTER
  ========================= */

  const filteredProducts = products.filter(p =>
    p.name?.toLowerCase().includes(
      search.toLowerCase()
    )
  );

  /* =========================
     LOGOUT
  ========================= */

  const handleLogout = () => {

    window.location.href =
      "http://localhost/pastry_system/staff_login.php";

  };

  /* =========================
     NAVIGATION
  ========================= */

  const navs = [

    {
      name: "Dashboard",
      path: "/pastry_system/staff"
    },

    {
      name: "Orders",
      path: "/orders"
    },

    {
      name: "Products",
      path: "/products"
    },

    {
      name: "Customers",
      path: "/customers"
    }

  ];

  return (

    <nav className="sticky top-0 z-[99999] bg-white/90 backdrop-blur-xl border-b border-gray-100 px-6 xl:px-10 py-5">

      <div className="flex items-center justify-between">

        {/* LEFT */}

        <div className="flex items-center gap-14">

          <Link
            to="/pastry_system/staff"
            className="flex items-center gap-4"
          >

            <img
              src="http://localhost/pastry_system/uploads/logo.jpg"
              alt="Logo"
              className="h-14 w-auto object-contain"
            />

            <div>

              <h1 className="text-[28px] font-bold italic leading-none text-black">
                Pastry
                <span className="text-[#d4af37]">
                  {" "}Project
                </span>
              </h1>

              <p className="text-[8px] uppercase tracking-[0.35em] text-gray-400 mt-1">
                staff management panel
              </p>

            </div>

          </Link>

          {/* NAV LINKS */}

          <div className="hidden lg:flex items-center gap-10">

            {navs.map(nav => (

              <Link
                key={nav.path}
                to={nav.path}
                className={`relative text-[10px] uppercase tracking-[0.3em] transition-all duration-300 ${
                  location.pathname === nav.path
                    ? "text-black font-semibold"
                    : "text-gray-400 hover:text-black"
                }`}
              >

                {nav.name}

                {location.pathname === nav.path && (
                  <span className="absolute left-0 -bottom-2 w-full h-[2px] rounded-full bg-[#d4af37]" />
                )}

              </Link>

            ))}

          </div>

        </div>

        {/* RIGHT */}

        <div className="flex items-center gap-4">

          {/* SEARCH */}

          <div
            ref={searchRef}
            className="relative"
          >

            <button
              onClick={() =>
                setOpenSearch(!openSearch)
              }
              className="w-12 h-12 rounded-full flex items-center justify-center text-gray-500 hover:bg-gray-100 transition-all"
            >

              <Search size={20} />

            </button>

            {openSearch && (

              <div className="absolute right-0 top-[65px] w-[380px] bg-white border border-gray-100 rounded-[28px] shadow-2xl overflow-hidden">

                <div className="flex items-center gap-3 px-5 py-4 border-b border-gray-100">

                  <Search
                    size={18}
                    className="text-gray-400"
                  />

                  <input
                    autoFocus
                    type="text"
                    placeholder="Search products..."
                    value={search}
                    onChange={(e) =>
                      setSearch(e.target.value)
                    }
                    className="flex-1 text-[13px] outline-none"
                  />

                  <button
                    onClick={() => {
                      setOpenSearch(false);
                      setSearch("");
                    }}
                    className="text-gray-400 hover:text-black"
                  >

                    <X size={18} />

                  </button>

                </div>

                <div className="max-h-[340px] overflow-y-auto p-3">

                  {filteredProducts.map(product => (

                    <div
                      key={product.id}
                      className="flex items-center gap-3 p-2 rounded-2xl hover:bg-gray-50 transition-all cursor-pointer"
                    >

                      <img
                        src={`http://localhost/pastry_system/uploads/${product.image}`}
                        alt=""
                        className="w-12 h-12 rounded-xl object-cover border border-gray-100"
                      />

                      <div>

                        <h3 className="text-[13px] font-semibold text-black">
                          {product.name}
                        </h3>

                        <p className="text-[10px] text-gray-400 uppercase tracking-wider">
                          {product.category}
                        </p>

                      </div>

                    </div>

                  ))}

                </div>

              </div>

            )}

          </div>

          {/* NOTIFICATIONS */}

          <div
            ref={notifRef}
            className="relative"
          >

            <button
              onClick={() =>
                setOpenNotif(!openNotif)
              }
              className="relative w-12 h-12 rounded-full flex items-center justify-center text-gray-500 hover:bg-gray-100 transition-all"
            >

              <Bell size={20} />

            </button>

            {openNotif && (

              <div className="absolute right-0 top-[65px] w-[320px] bg-white border border-gray-100 rounded-[28px] shadow-2xl overflow-hidden">

                <div className="px-5 py-4 border-b border-gray-100">

                  <h4 className="text-[10px] uppercase tracking-[0.3em] text-gray-500 font-bold">
                    Staff Notifications
                  </h4>

                </div>

                <div className="p-5 space-y-4">

                  <div className="flex items-start gap-3">

                    <ClipboardList
                      size={18}
                      className="text-[#d4af37]"
                    />

                    <div>

                      <p className="text-[13px] font-semibold">
                        New Order Received
                      </p>

                      <p className="text-[11px] text-gray-400">
                        A customer placed a new order.
                      </p>

                    </div>

                  </div>

                  <div className="flex items-start gap-3">

                    <Package
                      size={18}
                      className="text-[#d4af37]"
                    />

                    <div>

                      <p className="text-[13px] font-semibold">
                        Inventory Updated
                      </p>

                      <p className="text-[11px] text-gray-400">
                        Product stocks were updated.
                      </p>

                    </div>

                  </div>

                </div>

              </div>

            )}

          </div>

          {/* ACCOUNT */}

          <div
            ref={accountRef}
            className="relative"
          >

            <button
              onClick={() =>
                setOpenAccount(!openAccount)
              }
              className="w-12 h-12 rounded-full bg-gray-100 border border-gray-200 flex items-center justify-center hover:border-[#d4af37] transition-all"
            >

              <User
                size={20}
                className="text-gray-700"
              />

            </button>

            {openAccount && (

              <div className="absolute right-0 top-[65px] w-[240px] bg-white border border-gray-100 rounded-[28px] shadow-2xl overflow-hidden">

                <div className="px-5 py-4 border-b border-gray-100">

                  <p className="text-[10px] uppercase tracking-[0.2em] text-gray-400">
                    Staff Account
                  </p>

                  <h3 className="text-[16px] text-black mt-1 font-semibold">
                    Staff Panel
                  </h3>

                </div>

                <div className="p-2">

                  <button
                    onClick={() => {
                      navigate("/orders");
                      setOpenAccount(false);
                    }}
                    className="w-full flex items-center gap-3 px-4 py-3 rounded-2xl hover:bg-gray-50 text-[13px] transition-all group"
                  >

                    <Package
                      size={16}
                      className="text-gray-400 group-hover:text-black"
                    />

                    Orders

                  </button>

                  <button
                    onClick={() => {
                      navigate("/customers");
                      setOpenAccount(false);
                    }}
                    className="w-full flex items-center gap-3 px-4 py-3 rounded-2xl hover:bg-gray-50 text-[13px] transition-all group"
                  >

                    <Users
                      size={16}
                      className="text-gray-400 group-hover:text-black"
                    />

                    Customers

                  </button>

                  <button
                    onClick={handleLogout}
                    className="w-full flex items-center gap-3 px-4 py-3 rounded-2xl hover:bg-red-50 text-red-500 text-[13px] transition-all"
                  >

                    <LogOut size={16} />

                    Logout

                  </button>

                </div>

              </div>

            )}

          </div>

        </div>

      </div>

    </nav>

  );

}
